\end{enumerate}

\label{prop:thick_C_repository}
Let $W\subset\mathbb{N}$. 
The following are equivalent.
\begin{enumerate}
\item
\label{item1ofthepropositiononequivalentcontainment3}
For every thick set $A\subset\mathbb{N}$ there exist infinite sets $B\subset\mathbb{N}$, $C\subset W$ such that $B+C\subset A$.
\item
\label{item1.5ofthepropositiononequivalentcontainment3}
For every piecewise syndetic set $A\subset\mathbb{N}$ there exist infinite sets $B\subset\mathbb{N}$, $C\subset W$ such that $B+C\subset A$.
\item
\label{item2ofthepropositiononequivalentcontainment3}
$W$ is syndetic.
\end{enumerate}

The implication
$
\eqref{item2ofthepropositiononequivalentcontainment3}
\Rightarrow
\eqref{item1.5ofthepropositiononequivalentcontainment3}
$
follows from \cref{prop_syndeticB+C} and the implication $
\eqref{item1.5ofthepropositiononequivalentcontainment3}
\Rightarrow
\eqref{item1ofthepropositiononequivalentcontainment3}
$ is trivial.
For the final direction $
\eqref{item1ofthepropositiononequivalentcontainment3}
\Rightarrow
\eqref{item2ofthepropositiononequivalentcontainment3}
$, assume that $W$ is not syndetic and so for every $n\in\mathbb{N}$, there exist $a_n,b_n\in\mathbb{N}$ with $|b_n-a_n|\geq 2n$ and such that $W\cap [a_n,b_n]=\varnothing$. Then the set  $A=\bigcup_{n\in\mathbb{N}} [a_{n}+n,b_{n}]$ is a thick set with the property that any shift of it $A-t$ has finite intersection with $W$. Therefore one can not find  infinite sets $B\subset\mathbb{N}$, $C\subset W$ such that $B+C\subset A$.

